        )
        .is_ok());
        assert_eq!(tuneable.schedule(&mut state, &input), 1.into());
        assert!(TuneableScheduledMutator::set_mutation_probabilities(
            &mut state,
            vec![1.0, 0.0, 0.0]
        )
        .is_ok());
        assert_eq!(tuneable.schedule(&mut state, &input), 0.into());

